// Importaciones necesarias de React, estilos y Firebase
import React, { useState, useEffect } from "react";
import "./InicioAdmin.css"; // Estilos compartidos o similares al admin
import { useAuth } from "../context/authContext"; // Hook personalizado para autenticación
import { get, ref, update } from "firebase/database"; // Funciones de Firebase Realtime Database
import { useNavigate } from "react-router-dom"; // Para redireccionar
import { auth, rtdb } from "../firebase"; // Configuración de Firebase
import {
  RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar,
  BarChart, Bar, XAxis, YAxis, Tooltip,
  LineChart, Line, Legend,
  PieChart, Pie, Cell,
} from "recharts";

import sha256 from 'js-sha256';

// Componente principal para la vista del conductor
const InicioConductor = () => {
  // Estado para manejar qué sección se muestra en pantalla
  const [seccion, setSeccion] = useState("inicio");

  // Estado para almacenar y editar la información del perfil del conductor
  const [perfil, setPerfil] = useState(null);
  const [perfilEdit, setPerfilEdit] = useState(null);

  // Estado para almacenar evaluación del conductor
  const [evaluacion, setEvaluacion] = useState(null);

  // Estado para controlar qué campos son editables en el perfil
  const [camposEditables, setCamposEditables] = useState({
    nombre: false,
    correo: false,
    direccion: false,
    contraseña: false,
  });

  // Estado para controlar si mostrar info adicional (emociones, tiempo, seguridad)
  const [mostrarInfo, setMostrarInfo] = useState({ emociones: false, tiempo: false, seguridad: false });

  // Colores para UI (ejemplo)
  const colores = ["#ffa94d", "#f2a65a", "#e07b39", "#8884d8", "#a29bfe"];

  // Función para convertir segundos a minutos con dos decimales
  const convertirMinutos = (segundos) => (segundos / 60).toFixed(2);

  // Funciones y hooks del contexto de autenticación y navegación
  const { logout } = useAuth();
  const navigate = useNavigate();

  // Función para encriptar contraseña (usando sha256)
  const encriptarContrasena = (password) => {
    return sha256(password);
  };

  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (uid) {
      const perfilRef = ref(rtdb, `conductores/${uid}`);
      get(perfilRef).then((snapshot) => {
        if (snapshot.exists()) {
          let data = snapshot.val();

          // 🔁 Función para convertir todos los números a enteros (recursivo)
          const convertirEnteros = (obj) => {
            const nuevo = {};
            for (const key in obj) {
              if (typeof obj[key] === "number") {
                nuevo[key] = Math.round(obj[key]); // Cambia a floor() si quieres truncar
              } else if (typeof obj[key] === "object" && obj[key] !== null) {
                nuevo[key] = convertirEnteros(obj[key]); // Procesa objetos anidados
              } else {
                nuevo[key] = obj[key];
              }
            }
            return nuevo;
          };

          data = convertirEnteros(data); // 🔁 Aplicamos la conversión

          setPerfil(data);
          setPerfilEdit(data);
          setEvaluacion(data.evaluacion || {});
        }
      });
    }
  }, []);

  // Función para convertir segundos a minutos y segundos
  const aMinutosYSegundos = (segundos) => {
    const mins = Math.floor(segundos / 60);
    const segs = Math.round(segundos % 60);
    return `${mins} min ${segs} seg`;
  };


  // useEffect para cargar perfil y evaluación al iniciar componente
  useEffect(() => {
    const uid = auth.currentUser?.uid;
    if (uid) {
      const perfilRef = ref(rtdb, `conductores/${uid}`);
      get(perfilRef).then((snapshot) => {
        if (snapshot.exists()) {
          const data = snapshot.val();
          setPerfil(data);
          setPerfilEdit(data);
          setEvaluacion(data.evaluacion || {});
        }
      });
    }
  }, []);

  // Función para manejar cambio en campos editables (excepto contraseña)
  const handleChange = (e) => {
    const { name, value } = e.target;
    setPerfilEdit({ ...perfilEdit, [name]: value });
    setPerfil({ ...perfil, [name]: value });
    setCamposEditables({ ...camposEditables, [name]: false });
  };

  // Función para manejar cambio de contraseña con encriptación
  const handleChangePassword = (e) => {
    const { value } = e.target;
    const passwordEncriptada = encriptarContrasena(value);
    setPerfilEdit({ ...perfilEdit, contraseña: passwordEncriptada });
    setPerfil({ ...perfil, contraseña: passwordEncriptada });
    setCamposEditables({ ...camposEditables, contraseña: false });
  };

  // Función para actualizar perfil en Firebase
  const handleActualizarPerfil = async () => {
    const uid = auth.currentUser?.uid;
    if (!uid) return alert("Usuario no autenticado");

    try {
      await update(ref(rtdb, `conductores/${uid}`), perfilEdit);
      alert("Datos actualizados correctamente");
    } catch (error) {
      console.error("Error al actualizar perfil:", error);
      alert("Hubo un error al guardar los cambios");
    }
  };

  // Función para cerrar sesión y redirigir
  const cerrarSesion = async () => {
    await logout();
    navigate("/login");
  };



  return (
    <div className="contenedor">
      {/* Barra lateral de navegación */}
      <aside className="sidebar">
        {/* Logo */}
        <div className="logo-container">
          <img src="./imageenes/logo.png" alt="Logo Traslado y Transporte" className="logo" />
        </div>

        {/* Botones de navegación */}
        {["inicio", "perfil", "datos"].map((item) => (
          <button
            key={item}
            className={`boton ${seccion === item ? "activo" : ""}`} // Agrega clase "activo" si es la sección actual
            onClick={() => setSeccion(item)} // Cambia la sección
          >
            {item.toUpperCase()} {/* Muestra el nombre en mayúsculas */}
          </button>
        ))}

        {/* Botón de cerrar sesión */}
        <button className="boton" onClick={cerrarSesion}>
          CERRAR SESIÓN
        </button>
      </aside>

      {/* Contenido principal */}
      <main className="contenido">
        {/* Sección INICIO con bienvenida personalizada */}
        {seccion === "inicio" && perfil && (
          <div className="login-form-container">
            <div className="login-card">
              <h1>BIENVENIDO</h1>
              <h2>CONDUCTOR</h2>
              <h2>{perfil.nombre?.toUpperCase()}</h2> {/* Nombre del conductor en mayúsculas */}
            </div>
          </div>
        )}



        {seccion === "perfil" && perfil && (
          <section className="perfil-seccion">
            <div className="perfil-encabezado">
              <h1 className="perfil-titulo">MI PERFIL</h1>
              <img src="./imageenes/conductor.png" alt="Avatar Conductor" className="perfil-avatar" />
            </div>

            <div className="perfil-card">
              {["nombre", "correo", "direccion", "contraseña"].map((campo) => (
                <div key={campo} className="perfil-campo">
                  <label>{campo.toUpperCase()}</label>
                  <div className="perfil-input-container">
                    <input
                      type={campo === "contraseña" ? "password" : "text"}
                      value={perfilEdit[campo] || ""}
                      onChange={(e) => {
                        const valor = e.target.value;

                        // Validación para el nombre: no permite números
                        if (campo === "nombre" && /\d/.test(valor)) return;

                        // Validación para la dirección: máximo 3 dígitos numéricos
                        if (campo === "direccion") {
                          const numeros = valor.match(/\d+/g); // Extrae todos los números
                          if (numeros && numeros.some(num => num.length > 3)) return;
                        }

                        setPerfilEdit({ ...perfilEdit, [campo]: valor });
                      }}
                      readOnly={!camposEditables[campo]}
                      className={camposEditables[campo] ? "editable" : ""}
                    />

                    <button
                      className="btn-editar"
                      onClick={() =>
                        setCamposEditables({
                          ...camposEditables,
                          [campo]: !camposEditables[campo],
                        })
                      }
                    >
                      ✏️
                    </button>
                  </div>

                  {/* Leyenda para la contraseña */}
                  {campo === "contraseña" && camposEditables[campo] && (
                    <small className="leyenda-password">
                      Debe contener al menos 6 caracteres, una mayúscula y un número.
                    </small>
                  )}
                </div>
              ))}

              <button className="btn-guardar" onClick={handleActualizarPerfil}>
                Guardar Cambios
              </button>
            </div>
          </section>
        )}














        {seccion === "datos" && evaluacion && (
          <section className="seccion">
            <h1 style={{ marginBottom: "1rem" }}>Estadísticas del Desempeño del Conductor</h1>
            <p style={{ fontSize: "1.1rem", marginBottom: "2rem", maxWidth: "800px", margin: "auto" }}>
              En esta sección verás un resumen visual de tu progreso como conductor, con gráficos, análisis y consejos personalizados para seguir creciendo.
            </p>





            {/* 🎯 Progreso General */}
            <div style={{ textAlign: "center", marginBottom: "3rem" }}>
              <h3>📊 Desempeño General</h3>
              <p style={{ fontSize: "2rem", fontWeight: "bold", color: evaluacion.rating_general >= 75 ? "#00c49f" : evaluacion.rating_general >= 50 ? "#ffa500" : "#ff4d4f" }}>
                {evaluacion.rating_general}%
              </p>
              <p>
                {
                  evaluacion.rating_general >= 75
                    ? "✅ Excelente desempeño general. Sigue así."
                    : evaluacion.rating_general >= 50
                      ? "🟠 Buen avance, pero hay aspectos por mejorar."
                      : "🔴 Tu rendimiento es bajo. Necesitas practicar más escenarios clave."
                }
              </p>
            </div>


            {/* 🛡️ Evaluación General: Rating y Seguridad */}
            <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", justifyContent: "center", marginBottom: "3rem" }}>
              <div>
                <h3>⭐ Evaluación General</h3>
                <PieChart width={300} height={250}>
                  <Pie
                    data={[
                      { name: "Rating General", value: evaluacion.rating_general },
                      { name: "Seguridad", value: evaluacion.seguridad },
                    ]}
                    cx="50%" cy="50%" innerRadius={40} outerRadius={80}
                    dataKey="value" label
                  >
                    <Cell fill={colores[2]} />
                    <Cell fill={colores[3]} />
                  </Pie>
                  <Tooltip />
                  <Legend />
                </PieChart>
              </div>
              <div style={{ maxWidth: "350px" }}>
                <p><strong>Rating:</strong> {Math.round(evaluacion.rating_general)} — {evaluacion.rating_general < 60 ? "Los usuarios no están totalmente satisfechos." : "Buena percepción general."}</p>
                <p><strong>Seguridad:</strong> {Math.round(evaluacion.seguridad)} — {evaluacion.seguridad < 60 ? "Riesgos detectados en tu conducción." : "Muy buena seguridad."}</p>
                <button className="info-button" onClick={() => setMostrarInfo(prev => ({ ...prev, seguridad: !prev.seguridad }))}>ℹ️ Más info</button>
                {mostrarInfo.seguridad && (
                  <div className="info-box">
                    <p>El rating muestra la satisfacción del pasajero. Seguridad se mide por comportamiento en ruta. Mejora continua es clave.</p>
                  </div>
                )}
              </div>
            </div>

            {/* 🧠 Estado Emocional */}
            <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", justifyContent: "center", marginBottom: "3rem" }}>
              <div>
                <h3>🧠 Estado Emocional</h3>
                <BarChart width={300} height={250} data={[
                  { nombre: "Empatía", valor: evaluacion.empatia },
                  { nombre: "Enojo", valor: evaluacion.enojo },
                  { nombre: "Estrés", valor: evaluacion.estres },
                ]}>
                  <XAxis dataKey="nombre" />
                  <YAxis domain={[0, 100]} />
                  <Tooltip />
                  <Bar dataKey="valor" fill={colores[0]} />
                </BarChart>
              </div>
              <div style={{ maxWidth: "350px" }}>
                <p><strong>Empatía:</strong> {Math.round(evaluacion.empatia)} — {evaluacion.empatia < 60 ? "Trabaja en tu conexión con los pasajeros." : "Buen nivel de empatía."}</p>
                <p><strong>Enojo:</strong> {Math.round(evaluacion.enojo)} — {evaluacion.enojo > 50 ? "Cuida tu temperamento al conducir." : "Tienes buen control emocional."}</p>
                <p><strong>Estrés:</strong> {Math.round(evaluacion.estres)} — {evaluacion.estres > 50 ? "Alto nivel de estrés, considera pausas." : "Estrés bajo, excelente manejo."}</p>
                <button className="info-button" onClick={() => setMostrarInfo(prev => ({ ...prev, emociones: !prev.emociones }))}>ℹ️ Más info</button>
                {mostrarInfo.emociones && (
                  <div className="info-box">
                    <p>Estos indicadores reflejan tu estado emocional en ruta. Mantener emociones estables mejora la seguridad y experiencia del pasajero.</p>
                  </div>
                )}
              </div>
            </div>

            {/* 🌐 Comparación Emocional */}
            <div style={{ display: "flex", justifyContent: "center", marginBottom: "3rem" }}>
              <div>
                <h3>🌐 Comparación Emocional</h3>
                <RadarChart outerRadius={90} width={300} height={250} data={[
                  { aspecto: "Empatía", valor: evaluacion.empatia },
                  { aspecto: "Enojo", valor: 100 - evaluacion.enojo },
                  { aspecto: "Estrés", valor: 100 - evaluacion.estres },
                ]}>
                  <PolarGrid />
                  <PolarAngleAxis dataKey="aspecto" />
                  <PolarRadiusAxis angle={30} domain={[0, 100]} />
                  <Radar name="Estabilidad" dataKey="valor" stroke="#ff7300" fill="#ff7300" fillOpacity={0.6} />
                </RadarChart>
                <p style={{ maxWidth: "300px" }}>Este radar muestra estabilidad emocional: cuanto más grande el área, mejor tu desempeño mental.</p>
              </div>
            </div>

            {/* ⏱️ Tiempos y Pasajeros */}
            <div style={{ display: "flex", flexWrap: "wrap", gap: "2rem", justifyContent: "center", marginBottom: "3rem" }}>
              <div>
                <h3>⏱️ Tiempos y Pasajeros</h3>
                <LineChart width={300} height={250} data={[
                  { nombre: "Mejor Tiempo", valor: convertirMinutos(evaluacion.mejor_tiempo) },
                  { nombre: "Peor Tiempo", valor: convertirMinutos(evaluacion.peor_tiempo) },
                  { nombre: "Pasajeros", valor: evaluacion.cantidad_pasajeros },
                ]}>
                  <XAxis dataKey="nombre" />
                  <YAxis />
                  <Tooltip />
                  <Legend />
                  <Line type="monotone" dataKey="valor" stroke={colores[1]} />
                </LineChart>
              </div>
              <div style={{ maxWidth: "350px" }}>
                <p><strong>Pasajeros:</strong> {evaluacion.cantidad_pasajeros} — {evaluacion.cantidad_pasajeros < 10 ? "Experiencia limitada aún." : "Buen volumen de viajes."}</p>
                <p><strong>Mejor Tiempo:</strong> {convertirMinutos(evaluacion.mejor_tiempo)} min</p>
                <p><strong>Peor Tiempo:</strong> {convertirMinutos(evaluacion.peor_tiempo)} min — {evaluacion.peor_tiempo - evaluacion.mejor_tiempo > 2400 ? "Hay variaciones grandes." : "Buen ritmo constante."}</p>
                <button className="info-button" onClick={() => setMostrarInfo(prev => ({ ...prev, tiempo: !prev.tiempo }))}>ℹ️ Más info</button>
                {mostrarInfo.tiempo && (
                  <div className="info-box">
                    <p>El tiempo refleja tu rapidez y consistencia en la conducción. Apunta a mantener un ritmo estable y eficiente.</p>
                  </div>
                )}
              </div>
            </div>






            <div style={{ marginTop: "2rem", padding: "2rem", backgroundColor: "#fffaf0", borderRadius: "12px", maxWidth: "850px", margin: "auto", boxShadow: "0 4px 10px rgba(0,0,0,0.08)" }}>
              <h2 style={{ marginBottom: "1.5rem" }}>📊 Evaluación Detallada por Indicador</h2>

              {/* cantidad_pasajeros */}
              <p><strong>🧍‍♂️ Cantidad de Pasajeros: {evaluacion.cantidad_pasajeros}</strong><br />
                {
                  evaluacion.cantidad_pasajeros < 10
                    ? "🔸 Has transportado pocos pasajeros. Esto indica que aún estás adquiriendo experiencia real. Con más recorridos podrás mejorar la confianza y fluidez en el servicio."
                    : evaluacion.cantidad_pasajeros < 30
                      ? "🔹 Estás en una etapa de consolidación. Tu experiencia va creciendo, y eso te dará mayor seguridad en situaciones reales."
                      : "✅ Excelente, tienes una experiencia sólida con buena cantidad de pasajeros transportados. Eso aporta madurez y adaptación ante distintas situaciones."
                }</p>

              {/* empatia */}
              <p><strong>💬 Empatía: {Math.round(evaluacion.empatia)}/100</strong><br />
                {
                  evaluacion.empatia < 60
                    ? "🔸 Tu nivel de empatía es bajo. Esto puede reflejar falta de conexión con los pasajeros o desinterés. Trabaja en ponerte en el lugar del otro, ser más amable y demostrar atención real."
                    : evaluacion.empatia < 80
                      ? "🔹 Nivel aceptable, pero hay espacio para mejorar. Los pasajeros notan cuando hay un trato cordial. Saludar, escuchar y ayudar marca una gran diferencia."
                      : "✅ Excelente actitud. Transmites respeto y comprensión, lo que mejora la experiencia de viaje del usuario."
                }</p>

              {/* enojo */}
              <p><strong>😠 Control del Enojo: {Math.round(evaluacion.enojo)}/100</strong><br />
                {
                  evaluacion.enojo > 60
                    ? "🔴 Alto nivel de enojo detectado. Esto puede generar conflictos y poner en riesgo tu juicio al volante. Practica el autocontrol, evita reaccionar impulsivamente y respira antes de responder ante situaciones estresantes."
                    : evaluacion.enojo > 40
                      ? "🟠 Enojo moderado. A veces pierdes la calma, pero aún estás a tiempo de mejorar. Técnicas de respiración y manejo emocional te serán muy útiles."
                      : "✅ Buen control emocional. Esto es esencial para mantener un ambiente seguro y profesional en el transporte de personas."
                }</p>

              {/* estres */}
              <p><strong>📈 Nivel de Estrés: {Math.round(evaluacion.estres)}/100</strong><br />
                {
                  evaluacion.estres > 60
                    ? "🔴 Tu estrés es alto. Conducir bajo presión puede reducir tu concentración. Es recomendable organizar tus tiempos, dormir bien y evitar multitareas mientras conduces."
                    : evaluacion.estres > 40
                      ? "🟠 Estrés moderado. A veces te sientes presionado. Busca herramientas como meditación guiada, pausas breves entre turnos o música relajante para mejorar."
                      : "✅ Manejás muy bien tu estrés, eso te hace un conductor más estable y confiable."
                }</p>

              {/* mejor_tiempo */}
              <p><strong>⏱️ Mejor Tiempo de Respuesta: {Math.round(evaluacion.mejor_tiempo)} segundos</strong><br />
                {
                  evaluacion.mejor_tiempo < 15
                    ? "✅ Tiempos excelentes. Reaccionas rápido en situaciones importantes. Sigue entrenando con simuladores para mantener esa agilidad."
                    : evaluacion.mejor_tiempo < 30
                      ? "🟢 Buen tiempo de respuesta, aunque puede mejorarse con práctica. Reacciona con calma pero rapidez ante imprevistos."
                      : "🟠 Tiempo de reacción lento. Esto puede significar distracción o falta de entrenamiento. Mejora con simulaciones frecuentes y ejercicios de atención."
                }</p>

              {/* peor_tiempo */}
              <p><strong>⏱️ Peor Tiempo de Respuesta: {aMinutosYSegundos(evaluacion.peor_tiempo)}</strong><br />
                {
                  evaluacion.peor_tiempo > 60
                    ? "🔴 Tiempo de respuesta muy alto en momentos críticos. Puede significar desconexión o lentitud en la toma de decisiones. Necesitas entrenar reacciones automáticas ante escenarios comunes."
                    : evaluacion.peor_tiempo > 40
                      ? "🟠 En algunas ocasiones respondes lento. Enfócate en eliminar distracciones y mantener la concentración constante."
                      : "✅ Tus tiempos son bastante estables y dentro de los márgenes esperados."
                }
              </p>

              {/* rating_general */}
              <p><strong>🌟 Calificación General del Servicio: {Math.round(evaluacion.rating_general)}/100</strong><br />
                {
                  evaluacion.rating_general < 60
                    ? "🔸 Baja calificación por parte de los pasajeros. Esto puede reflejar fallas en trato, puntualidad o seguridad. Lee los comentarios y mejora la experiencia general que brindas."
                    : evaluacion.rating_general < 80
                      ? "🟡 Evaluación aceptable, pero no destacada. Revisa los puntos que podrías pulir para ofrecer una experiencia excelente."
                      : "✅ ¡Muy bien! Los usuarios aprecian tu servicio. Mantén esa actitud y profesionalismo."
                }</p>

              {/* seguridad */}
              <p><strong>🛡️ Seguridad al Conducir: {Math.round(evaluacion.seguridad)}/100</strong><br />
                {
                  evaluacion.seguridad < 60
                    ? "🔴 Nivel bajo de seguridad. Posibles comportamientos de riesgo. Urge reforzar conocimientos en conducción defensiva y respetar estrictamente las normas de tránsito."
                    : evaluacion.seguridad < 80
                      ? "🟠 Seguridad intermedia. Se recomienda mayor atención a detalles como uso del cinturón, velocidad adecuada y distancia con otros vehículos."
                      : "✅ Excelente. Conduces de forma segura y responsable, lo que genera confianza y protege a todos."
                }</p>
            </div>

          </section>
        )}












      </main>
    </div>
  );
};

// Exporta el componente para su uso en otras partes de la app
export default InicioConductor;