// src/components/graficos/DonutChart.js
import React from 'react';
import { PieChart, Pie, Cell, Tooltip } from 'recharts';

const COLORS = ['#8bc34a', '#f44336'];

export default function DonutChart({ titulo, valor, maximo = 100 }) {
  const data = [
    { name: 'Obtenido', value: valor },
    { name: 'Restante', value: maximo - valor }
  ];

  return (
    <div style={{ marginBottom: '2rem', textAlign: 'center' }}>
      <h4 style={{ color: '#33691e' }}>{titulo}</h4>
      <PieChart width={250} height={200}>
        <Pie
          data={data}
          cx="50%"
          cy="50%"
          innerRadius={50}
          outerRadius={70}
          dataKey="value"
        >
          {data.map((_, index) => (
            <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
          ))}
        </Pie>
        <Tooltip />
      </PieChart>
      <p style={{ marginTop: '0.5rem', color: '#555' }}>
        {valor >= 80
          ? "Excelente desempeño en este indicador."
          : valor >= 50
          ? "Desempeño aceptable, puede mejorar."
          : "Debe enfocarse en mejorar este aspecto."}
      </p>
    </div>
  );
}
