import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './login.css';
import { signInWithEmailAndPassword, sendPasswordResetEmail } from "firebase/auth";
import { getDatabase, ref, get } from "firebase/database";
import { auth } from "../firebase";

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showResetModal, setShowResetModal] = useState(false);
  const [resetEmail, setResetEmail] = useState('');
  const [loginAttempts, setLoginAttempts] = useState(0);
  const [isBlocked, setIsBlocked] = useState(false);
  const [errorMessage, setErrorMessage] = useState('');
  const [showErrorModal, setShowErrorModal] = useState(false);


  
  // Hook para redireccionar entre rutas
  const navigate = useNavigate();

const handleLogin = async (e) => {
  e.preventDefault(); // Evita que el formulario recargue la página
  if (isBlocked) return; // Bloquea la acción si el usuario está temporalmente bloqueado

  try {
    // Sanitización de entradas para prevenir ataques XSS y evitar inyecciones
    const cleanEmail = sanitizeInput(email.trim());
    const cleanPassword = sanitizeInput(password.trim());

    // Inicio de sesión con Firebase usando credenciales saneadas
    const userCredential = await signInWithEmailAndPassword(auth, cleanEmail, cleanPassword);
    const user = userCredential.user; // Usuario autenticado

    const db = getDatabase();

    // Referencias a nodos admin y conductor
    const adminRef = ref(db, 'administradores/' + user.uid);
    const driverRef = ref(db, 'conductores/' + user.uid);

    // Obtener datos admin y conductor (si existen)
    const [adminSnapshot, driverSnapshot] = await Promise.all([
      get(adminRef),
      get(driverRef)
    ]);

    // Si es administrador
    if (adminSnapshot.exists()) {
      const adminData = adminSnapshot.val();

      if (adminData.estado && adminData.estado.toLowerCase() !== "activo") {
        setErrorMessage("Tu cuenta de administrador está inactiva. Contacta con soporte.");
        setShowErrorModal(true);
        return;
      }

      // Guardar perfil admin localmente y navegar a su dashboard
      localStorage.setItem("adminPerfil", JSON.stringify(adminData));
      navigate("/InicioAdmin");
      return;
    }

    // Si es conductor
    if (driverSnapshot.exists()) {
      const driverData = driverSnapshot.val();

      if (driverData.estado && driverData.estado.toLowerCase() !== "activo") {
        setErrorMessage("Tu cuenta de conductor está inactiva. Contacta con soporte.");
        setShowErrorModal(true);
        return;
      }

      // Guardar perfil conductor localmente y navegar a su dashboard
      localStorage.setItem("conductorPerfil", JSON.stringify(driverData));
      navigate("/InicioConductor");
      return;
    }

    // Si no es ni admin ni conductor
    setErrorMessage("Usuario no autorizado.");
    setShowErrorModal(true);

  } catch (error) {
    // Control de intentos fallidos de inicio de sesión
    const newAttempts = loginAttempts + 1;
    setLoginAttempts(newAttempts);
    setErrorMessage(`Correo o contraseña incorrectos. Intento ${newAttempts} de 3.`);
    setShowErrorModal(true);

    // Bloqueo temporal después de 3 intentos fallidos
    if (newAttempts >= 3) {
      setIsBlocked(true);
      setErrorMessage("Demasiados intentos. Espera 10 segundos antes de volver a intentar.");

      // Reinicia el contador después de 10 segundos
      setTimeout(() => {
        setLoginAttempts(0);
        setIsBlocked(false);
      }, 10000);
    }
  }
};


  // Función para restablecer la contraseña
  const handleResetPassword = async () => {
    try {
      await sendPasswordResetEmail(auth, resetEmail);
      alert("Correo de recuperación enviado. Revisa tu bandeja de entrada.");
      setShowResetModal(false);
    } catch (error) {
      alert("Error al enviar el correo de recuperación.");
    }
  };

  // Función para sanitizar entradas del usuario
  const sanitizeInput = (input) => {
    const cleaned = input.replace(/[<>/"'`;()&]/g, '');
    const lower = cleaned.toLowerCase();
    if (lower.includes("script") || lower.includes("alert") || lower.includes("onerror")) {
      return "";
    }
    return cleaned;
  };


  const validateEmail = (email) => {
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
  };


  return (
    <div className="contenedor">
      <div className="sidebar">
        <div className="logo-container">
          <img src="./imageenes/logo.png" alt="Logo Traslado y Transporte" className="logo" />
        </div>
        <button className="boton" onClick={() => navigate("/")}>INICIO</button>
        <a href="#nosotros" className="boton">NOSOTROS</a>
        <a href="#valores" className="boton">VALORES</a>
        <a href="#contactanos" className="boton">CONTACTANOS</a>
        <button className="boton activo">INICIAR SESIÓN</button>
      </div>

      <div className="login-form-container">
        <div className="login-card">
          <div className="avatar"></div>
          <h2>INICIAR SESIÓN</h2>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              const cleanEmail = sanitizeInput(email.trim());
              const cleanPassword = sanitizeInput(password.trim());

              // Validación personalizada
              if (!validateEmail(cleanEmail)) {
                setErrorMessage("Formato de correo inválido.");
                setShowErrorModal(true);
                return;
              }

              if (cleanPassword.length < 6) {
                setErrorMessage("La contraseña debe tener al menos 6 caracteres.");
                setShowErrorModal(true);
                return;
              }

              // Si todo está bien, sigue con el login
              handleLogin(e, cleanEmail, cleanPassword);
            }}
          >
            <label>USUARIO</label>
            <input
              type="email"
              placeholder="INGRESA TU CORREO ELECTRÓNICO"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
            <label>CONTRASEÑA</label>
            <input
              type="password"
              placeholder="*****"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
            <span className="forgot" onClick={() => setShowResetModal(true)}>
              ¿OLVIDASTE TU CONTRASEÑA?
            </span>
            <button type="submit" className="login-btn" disabled={isBlocked}>
              {isBlocked ? "ESPERANDO..." : "INICIAR SESIÓN"}
            </button>
            {!isBlocked && loginAttempts > 0 && (
              <p style={{ color: "red", marginTop: "10px" }}>
                Te quedan {3 - loginAttempts} intento(s)
              </p>
            )}
          </form>
        </div>
      </div>


      {showResetModal && (
        <div className="modal">
          <div className="modal-content">
            <h3>Recuperar Contraseña</h3>
            <input
              type="email"
              placeholder="Ingresa tu correo"
              value={resetEmail}
              onChange={(e) => setResetEmail(e.target.value)}
            />
            <div className="modal-buttons">
              <button onClick={handleResetPassword}>Enviar</button>
              <button onClick={() => setShowResetModal(false)}>Cancelar</button>
            </div>
          </div>
        </div>
      )}

      {showErrorModal && (
        <div className="modal">
          <div className="modal-content">
            <h3>Error</h3>
            <p>{errorMessage}</p>
            <div className="modal-buttons">
              <button onClick={() => setShowErrorModal(false)}>Cerrar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Login;