import { Routes, Route } from "react-router-dom";
import Inicio from "./components/home";
import Login from "./components/login";
import InicioAdmin from './components/inicio_admin';
import InicioConductor from './components/inicio_conductor'; // 👈 Agregado
import PrivateRoute from './components/PrivateRoute';
import { AuthProvider } from "./context/authContext";

function App() {
  return (
    <AuthProvider>
      <div className="App">
        <Routes>
          <Route path="/" element={<Inicio />} />
          <Route path="/login" element={<Login />} />
          
          {/* Admin protegido */}
          <Route path="/InicioAdmin" element={
            <PrivateRoute>
              <InicioAdmin />
            </PrivateRoute>
          } />

          {/* Conductor protegido */}
          <Route path="/InicioConductor" element={
            <PrivateRoute>
              <InicioConductor />
            </PrivateRoute>
          } />
        </Routes>
      </div>
    </AuthProvider>
  );
}

export default App;
