import React from 'react';
import { Link } from 'react-router-dom';
import './home.css';
function Home() {
  return (
    <div className="App">
      <div className="contenedor">
        <aside className="sidebar">
          <div className="logo-container">
            <img src="./imageenes/logo.png" alt="Logo Traslado y Transporte" className="logo" />
          </div>
          <nav>
            <a href="#inicio" className="boton">INICIO</a>
            <a href="#nosotros" className="boton">NOSOTROS</a>
            <a href="#valores" className="boton">VALORES</a>
            <a href="#contactanos" className="boton">CONTACTANOS</a>
            <Link to="/login" className="boton">INICIAR SESIÓN</Link> {/* ← aquí */}
          </nav>
        </aside>

        <main className="contenido">
          {/* Sección Nosotros */}
          <section className="seccion" id="nosotros">
            <div className="encabezado">
              <img src="./imageenes/ciudad.jpg" alt="Ciudad" className="fondo-ciudad" />
              <h1 className="titulo">NOSOTROS - TRASLADO Y TRANSPORTE</h1>
            </div>
            <div className="cuerpo">
              <img src="./imageenes/taxi.png" className="icono-taxi" alt="Taxi" />
              <p className="texto">
                Traslado y Transporte, una empresa dedicada al servicio de radiotaxi en la ciudad de Valdebruma, ofrece un servicio único: llevar a nuestros pasajeros de un punto A a un punto B, pero con el compromiso de hacer de cada viaje una experiencia memorable. Fundada por Ernesto Garrido, un excéntrico ingeniero, nos destacamos por la calidad y cuidado de nuestros vehículos, siempre impecablemente restaurados.
                
              </p>
            </div>
          </section>

          {/* Sección Valores */}
          <section className="seccion" id="valores">
            <div className="encabezado">
              <img src="./imageenes/ciudad1.jpg" alt="Ciudad" className="fondo-ciudad" />
              <h1 className="titulo">VALORES DE TRASLADO Y TRANSPORTE</h1>
            </div>
            <div className="valores-contenido">
              <div className="valor">
                <div className="flecha">MISION</div>
                <div className="caja-texto">
                  BRINDAR UN SERVICIO DE TRANSPORTE INNOVADOR, QUE NO SOLO LLEVE A NUESTROS PASAJEROS A SU DESTINO, SINO QUE LOS CONECTE CON LOS MOMENTOS MÁS IMPORTANTES DE SUS VIDAS. CADA VIAJE ES UNA EXPERIENCIA ÚNICA.
                </div>
              </div>
              <div className="valor">
                <div className="flecha">VISION</div>
                <div className="caja-texto">
                  SER LA EMPRESA DE TAXIS MÁS DESTACADA Y ENIGMÁTICA DEL SECTOR, NO SÓLO POR LA CALIDAD DE NUESTRO SERVICIO, SINO POR LA EXPERIENCIA QUE CADA PASAJERO VIVE EN CADA VIAJE.
                </div>
              </div>
            </div>
          </section>

          {/* Sección Contáctanos */}
          <section className="seccion" id="contactanos">
            <div className="header-seccion">
              <img src="./imageenes/fondo-ciudad.jpg" className="header-img" alt="Fondo ciudad" />
              <h1>CONTACTANOS</h1>
            </div>

            <div className="contacto-contenido">
              <div className="mapa">
                <iframe 
                  src="https://www.google.com/maps/embed?pb=!4v1744134564953!6m8!1m7!1spYkJ1tPRvjeQ3shVvTPiCA!2m2!1d-16.50552734430103!2d-68.13665324274673!3f284.40235591416916!4f-8.71962813709888!5f0.7820865974627469" 
                  width="100%" 
                  height="100%" 
                  style={{border: '0', borderRadius: '15px'}} 
                  allowFullScreen="" 
                  loading="lazy" 
                  referrerPolicy="no-referrer-when-downgrade"
                ></iframe>
              </div>
              <div className="iconos-contacto">
                <a href="https://wa.me/591XXXXXXXX" target="_blank" rel="noopener noreferrer">
                  <img src="./imageenes/whatsapp.png" alt="WhatsApp" />
                </a>
                <a href="https://facebook.com/" target="_blank" rel="noopener noreferrer">
                  <img src="./imageenes/facebook.png" alt="Facebook" />
                </a>
                <a href="https://traslado_y_trasporte.com" target="_blank" rel="noopener noreferrer">
                  <img src="./imageenes/internet.png" alt="Internet" />
                </a>
              </div>
            </div>
          </section>

        </main>
      </div>
    </div>
  );
}

export default Home;
