import React from 'react';
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer
} from 'recharts';

const DoubleBarChart = ({ data }) => {
  // Convertimos el array de objetos para usarlo como datos de barras
  const chartData = data.map(item => ({
    nombre: item.nombre,
    valor: item.valor,
    maximo: 10, // para comparar con el valor máximo posible
  }));

  return (
    <ResponsiveContainer width="100%" height={300}>
      <BarChart
        data={chartData}
        margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
      >
        <CartesianGrid strokeDasharray="3 3" />
        <XAxis dataKey="nombre" />
        <YAxis />
        <Tooltip />
        <Legend />
        <Bar dataKey="valor" fill="#7cb342" name="Valor actual" />
        <Bar dataKey="maximo" fill="#c8e6c9" name="Valor máximo" />
      </BarChart>
    </ResponsiveContainer>
  );
};

export default DoubleBarChart;
